ef="#seed-of-the-day"><text class="name" x="486" y="83.6" style="font-size:12px;text-anchor:middle">The Seed of the Day</text></a><a class="col-way begun" href="#seed-of-the-day-hunt"><circle cx="486" cy="96" r="6.4"/><text x="486" y="98.7">i</text><title>i · The Daily Hunt</title></a></g><g class="col-place isle lone"><a href="#gallery"><text class="name" x="500" y="307.6" style="font-size:12px;text-anchor:middle">The Gallery</text></a><a class="col-way done" href="#gallery-browse"><circle cx="500" cy="320" r="6.4"/><text x="500" y="322.7">i</text><title>i · Worlds hung for viewing</title></a></g><g class="col-place village untaught"><circle class="pip" cx="158" cy="330" r="3"/><text class="name" x="158" y="321.4" style="font-size:10.3px;text-anchor:middle">Questions &amp; Answers</text></g><g class="col-place village untaught"><circle class="pip" cx="352" cy="336" r="3"/><text class="name" x="352" y="327.4" style="font-size:10.3px;text-anchor:middle">The Glossary</text></g><g class="col-place isle untaught"><circle class="pip" cx="44" cy="128" r="4"/><text class="name" x="44" y="118.4" style="font-size:10.3px;text-anchor:middle">The Atlas</text></g><g class="col-place isle untaught"><circle class="pip" cx="52" cy="376" r="4"/><text class="name" x="52" y="366.4" style="font-size:10.3px;text-anchor:middle">The Primer</text></g><g class="col-next"><circle class="ring-a" cx="319.8" cy="214.4" r="8.3"/><circle class="ring-b" cx="319.8" cy="214.4" r="8.3"/><text transform="translate(326.8 220.9) rotate(43)" text-anchor="start" dy="0.36em">&#x261C;</text></g><g class="col-rose" transform="translate(542 384)"><circle r="12"/><path d="M0 -12 L2.8 -2.8 L12 0 L2.8 2.8 L0 12 L-2.8 2.8 L-12 0 L-2.8 -2.8 Z"/><text y="-16">N</text></g><text class="col-title" x="23" y="400">A Chart of the Lessons</text></svg>","card":"<div class="col-card"><p class="cc-verb">Eight lessons at</p><p class="cc-name">The Explorer</p><ol><li class="done"><span class="cc-n">i</span><a href="#explorer-number">A world from a number</a><em>3 of 3</em></li><li class="done"><span class="cc-n">ii</span><a href="#explorer-land">The Land</a><em>6 of 6</em></li><li class="done"><span class="cc-n">iii</span><a href="#explorer-strand">The Strand</a><em>4 of 4</em></li><li class="done"><span class="cc-n">iv</span><a href="#explorer-hand">The Hand</a><em>6 of 6</em></li><li class="done"><span class="cc-n">v</span><a href="#explorer-glass">The Surveyor's Glass</a><em>6 of 7<span class="cc-away">one on a tablet</span></em></li><li class="begun"><span class="cc-n">vi</span><a href="#explorer-places">Places on the chart</a><em>2 of 4</em></li><li class="none"><span class="cc-n">vii</span><a href="#explorer-press">The Press</a><em>0 of 3</em></li><li class="none"><span class="cc-n">viii</span><a href="#explorer-table">The Chart Table</a><em>0 of 4</em></li></ol><p class="cc-go"><a href="#explorer-take-road">Go on at vi · Places on the chart</a></p></div>","caption":"Every room that teaches, and how far you have come: a red seal is a lesson done, a red rim one begun, the red road is the way you have come; the lit room is the one you are reading, and the hand points at your next step.","seat":"head","cardLeft":"0","cardTop":"0","foldWidth":"52rem"};
  if (P.seat === "none") return "none";
  const style = document.createElement("style");
  style.textContent = P.css;
  document.head.append(style);
  document.body.insertAdjacentHTML("afterbegin", P.defs);
  if (P.seat === "head" || P.seat === "head-card") {
    const opening = document.querySelector(".primer .opening");
    const card = P.seat === "head-card" ? P.card.replace('class="col-card"', 'class="col-card" style="left:' + P.cardLeft + ';top:' + P.cardTop + '"') : "";
    opening.insertAdjacentHTML("beforebegin", '<div class="col-head col-paper"><div class="col-frame">' + P.svg + card + '</div>' + (P.caption ? '<p class="col-caption">' + P.caption + '</p>' : '') + '</div>');
    dispatchEvent(new Event("scroll"));
  }
  if (P.seat === "slip") {
    const body = document.querySelector("#index .slip-body");
    const list = body.querySelector("ol.index");
    list.insertAdjacentHTML("beforebegin", '<div class="col-slipchart col-paper">' + P.svg + '</div>' + (P.caption ? '<p class="col-caption">' + P.caption + '</p>' : ''));
  }
  if (P.seat === "fold" || P.seat === "fold-shut") {
    const folio = document.querySelector(".corner.tr");
    const line = folio.querySelector(".dateline");
    line.insertAdjacentHTML("afterend", '<p style="margin:0;text-align:right"><span class="col-press' + (P.seat === "fold-shut" ? ' shut' : '') + '">the chart of lessons</span></p>');
    dispatchEvent(new Event("resize"));
    if (P.seat === "fold-shut") return P.seat;
    const r = folio.getBoundingClientRect();
    const card = P.card.replace('class="col-card"', 'class="col-card" style="left:' + P.cardLeft + ';top:' + P.cardTop + '"');
    document.body.insertAdjacentHTML("beforeend", '<div class="col-fold col-night" style="width:' + P.foldWidth + ';right:' + (innerWidth - r.right) + 'px;top:' + (r.bottom + 30 + scrollY) + 'px">' + P.svg + card + '<p class="col-key">the chart of lessons: every room with steps, and how far you have come</p></div>');
  }
  return P.seat;
})()

