.col-paper .col-road.inked{stroke:var(--iron-red);stroke-width:2.3}
.col-paper .col-route{fill:none;stroke:var(--ink-faded);stroke-width:2.1;stroke-linecap:round;stroke-dasharray:.1 4.6}
